ALTER TABLE inv_transfer_line ADD CONSTRAINT inv_transfer_parent_line UNIQUE(country_id,transfer_id,id);
ALTER TABLE inv_replenish_link ADD COLUMN transfer_id jxc_safe_id,ADD COLUMN transfer_line_id jxc_safe_id,ADD COLUMN purchase_order_id jxc_safe_id,ADD COLUMN purchase_order_line_id jxc_safe_id;
UPDATE inv_replenish_link SET transfer_id=CASE WHEN exec_doc_type='INV_TRANSFER' THEN exec_doc_id END,transfer_line_id=CASE WHEN exec_doc_type='INV_TRANSFER' THEN exec_line_id END,purchase_order_id=CASE WHEN exec_doc_type='PUR_ORDER' THEN exec_doc_id END,purchase_order_line_id=CASE WHEN exec_doc_type='PUR_ORDER' THEN exec_line_id END;
ALTER TABLE inv_replenish_link ADD FOREIGN KEY(country_id,transfer_id,transfer_line_id) REFERENCES inv_transfer_line(country_id,transfer_id,id),ADD FOREIGN KEY(country_id,purchase_order_id,purchase_order_line_id) REFERENCES pur_order_line(country_id,order_id,id);
ALTER TABLE inv_replenish_link ADD CONSTRAINT inv_replenish_execution_identity CHECK((exec_doc_type='INV_TRANSFER' AND transfer_id=exec_doc_id AND transfer_line_id=exec_line_id AND transfer_id IS NOT NULL AND transfer_line_id IS NOT NULL AND purchase_order_id IS NULL AND purchase_order_line_id IS NULL) OR (exec_doc_type='PUR_ORDER' AND purchase_order_id=exec_doc_id AND purchase_order_line_id=exec_line_id AND purchase_order_id IS NOT NULL AND purchase_order_line_id IS NOT NULL AND transfer_id IS NULL AND transfer_line_id IS NULL));
CREATE TRIGGER inv_replenish_link_immutable BEFORE UPDATE OR DELETE ON inv_replenish_link FOR EACH ROW EXECUTE FUNCTION jxc_ar_fact_immutable();
